const input = $('When Executed by Another Workflow').first().json;
const results = $input.all();
const found = results.length > 0 && results[0].json.phone;
const row = found ? results[0].json : {};

const is_new_session = !found;

// Stale check: >3 hours since last_seen_at
let is_stale_session = false;
if (found && row.last_seen_at) {
  const lastSeen = new Date(row.last_seen_at).getTime();
  const receivedAt = new Date(input.received_at || Date.now()).getTime();
  const threeHoursMs = 3 * 60 * 60 * 1000;
  is_stale_session = (receivedAt - lastSeen) > threeHoursMs;
}

return [{
  json: {
    phone: input.phone,
    display_name: found ? (row.display_name || input.display_name) : (input.display_name || ''),
    session_status: found ? (row.session_status || 'active') : 'active',
    short_memory: found ? (row.short_memory || '') : '',
    last_intent: found ? (row.last_intent || '') : '',
    last_user_message: found ? (row.last_user_message || '') : '',
    last_bot_message: found ? (row.last_bot_message || '') : '',
    last_seen_at: found ? (row.last_seen_at || '') : '',
    message_count: found ? (parseInt(row.message_count) || 0) : 0,
    needs_human: found ? (row.needs_human === 'true' || row.needs_human === true) : false,
    is_new_session: is_new_session,
    is_stale_session: is_stale_session
  }
}];
